function parseFilters(filterJson) {
  const filters = JSON.parse(filterJson);

  return filters.map(filter => {
    if (filter.type === "int_increase") {
      return {
        attribute: filter.attribute,
        value: parseInt(filter.value),
        type: filter.type
      };
    } else {
      return filter;
    }
  });
}
